    50→// BatchVerifyDepositsSignatures batch verifies deposit signatures.
    51→func BatchVerifyDepositsSignatures(ctx context.Context, deposits []*ethpb.Deposit) (bool, error) {
    52→	var err error
    53→	domain, err := signing.ComputeDomain(params.BeaconConfig().DomainDeposit, nil, nil)
    54→	if err != nil {
    55→		return false, err
    56→	}
    57→
    58→	if err := verifyDepositDataWithDomain(ctx, deposits, domain); err != nil {
    59→		log.WithError(err).Debug("Failed to batch verify deposits signatures, will try individual verify")
    60→		return false, nil
    61→	}
    62→	return true, nil
    63→}
