    66→func BatchVerifyPendingDepositsSignatures(ctx context.Context, deposits []*ethpb.PendingDeposit) (bool, error) {
    67→	var err error
    68→	domain, err := signing.ComputeDomain(params.BeaconConfig().DomainDeposit, nil, nil)
