    80→// IsValidDepositSignature returns whether deposit_data is valid
    81→// def is_valid_deposit_signature(pubkey: BLSPubkey, withdrawal_credentials: Bytes32, amount: uint64, signature: BLSSignature) -> bool:
    82→//
    83→//	deposit_message = DepositMessage( pubkey=pubkey, withdrawal_credentials=withdrawal_credentials, amount=amount, )
    84→//	domain = compute_domain(DOMAIN_DEPOSIT)  # Fork-agnostic domain since deposits are valid across forks
    85→//	signing_root = compute_signing_root(deposit_message, domain)
    86→//	return bls.Verify(pubkey, signing_root, signature)
    87→func IsValidDepositSignature(data *ethpb.Deposit_Data) (bool, error) {
    88→	domain, err := signing.ComputeDomain(params.BeaconConfig().DomainDeposit, nil, nil)
    89→	if err != nil {
    90→		return false, err
    91→	}
    92→	if err := verifyDepositDataSigningRoot(data, domain); err != nil {
    93→		// Ignore this error as in the spec pseudo code.
    94→		log.WithError(err).Debug("Skipping deposit: could not verify deposit data signature")
    95→		return false, nil
    96→	}
    97→	return true, nil
    98→}
