   177→func verifyPendingDepositDataWithDomain(ctx context.Context, deps []*ethpb.PendingDeposit, domain []byte) error {
   178→	if len(deps) == 0 {
   179→		return nil
   180→	}
   181→	pks := make([]bls.PublicKey, len(deps))
   182→	sigs := make([][]byte, len(deps))
   183→	msgs := make([][32]byte, len(deps))
   184→	for i, dep := range deps {
   185→		if ctx.Err() != nil {
   186→			return ctx.Err()
   187→		}
   188→		if dep == nil {
   189→			return errors.New("nil deposit")
   190→		}
   191→		dpk, err := bls.PublicKeyFromBytes(dep.PublicKey)
   192→		if err != nil {
   193→			return err
   194→		}
   195→		pks[i] = dpk
   196→		sigs[i] = dep.Signature
   197→		depositMessage := &ethpb.DepositMessage{
   198→			PublicKey:             dep.PublicKey,
   199→			WithdrawalCredentials: dep.WithdrawalCredentials,
   200→			Amount:                dep.Amount,
   201→		}
   202→		sr, err := signing.ComputeSigningRoot(depositMessage, domain)
   203→		if err != nil {
   204→			return err
   205→		}
   206→		msgs[i] = sr
   207→	}
   208→	verify, err := bls.VerifyMultipleSignatures(sigs, msgs, pks)
   209→	if err != nil {
   210→		return errors.Errorf("could not verify multiple signatures: %v", err)
   211→	}
   212→	if !verify {
   213→		return errors.New("one or more deposit signatures did not verify")
   214→	}
   215→	return nil
   216→}
