    21→			drs, err := unmarshalDeposits(requestListInSSZBytes, limits.Deposits)
    22→			if err != nil {
    23→				return nil, err
    24→			}
    25→			requests.Deposits = drs
    26→		case WithdrawalRequestType:
    27→			wrs, err := unmarshalWithdrawals(requestListInSSZBytes, limits.Withdrawals)
    28→			if err != nil {
    29→				return nil, err
    30→			}
    31→			requests.Withdrawals = wrs
    32→		case ConsolidationRequestType:
    33→			crs, err := unmarshalConsolidations(requestListInSSZBytes, limits.Consolidations)
    34→			if err != nil {
    35→				return nil, err
    36→			}
