   123→// VerifyBlockDepositLength
   124→//
   125→// Spec definition:
   126→//
   127→//	# [Modified in Electra:EIP6110]
   128→//	  # Disable former deposit mechanism once all prior deposits are processed
   129→//	  eth1_deposit_index_limit = min(state.eth1_data.deposit_count, state.deposit_requests_start_index)
   130→//	  if state.eth1_deposit_index < eth1_deposit_index_limit:
   131→//	      assert len(body.deposits) == min(MAX_DEPOSITS, eth1_deposit_index_limit - state.eth1_deposit_index)
   132→//	  else:
   133→//	      assert len(body.deposits) == 0
   134→func VerifyBlockDepositLength(body interfaces.ReadOnlyBeaconBlockBody, state state.BeaconState) error {
   135→	eth1Data := state.Eth1Data()
   136→	requestsStartIndex, err := state.DepositRequestsStartIndex()
   137→	if err != nil {
   138→		return errors.Wrap(err, "failed to get requests start index")
   139→	}
   140→	eth1DepositIndexLimit := min(eth1Data.DepositCount, requestsStartIndex)
   141→	if state.Eth1DepositIndex() < eth1DepositIndexLimit {
   142→		if uint64(len(body.Deposits())) != min(params.BeaconConfig().MaxDeposits, eth1DepositIndexLimit-state.Eth1DepositIndex()) {
   143→			return fmt.Errorf("incorrect outstanding deposits in block body, wanted: %d, got: %d", min(params.BeaconConfig().MaxDeposits, eth1DepositIndexLimit-state.Eth1DepositIndex()), len(body.Deposits()))
   144→		}
   145→	} else {
   146→		if len(body.Deposits()) != 0 {
   147→			return fmt.Errorf("incorrect outstanding deposits in block body, wanted: %d, got: %d", 0, len(body.Deposits()))
   148→		}
   149→	}
   150→	return nil

